// === Companies to scrape via Lever Public Postings API ===
// Edit this list to add/remove coverage. Each slug must match the
// company's Lever board (found in the careers URL after /lever.co/).
// Verify a slug by hitting https://api.lever.co/v0/postings/<slug>?mode=json
// in a browser — should return a JSON array of job objects.
//
// Most companies have moved off Lever to Greenhouse / Workday / Ashby.
// Confirmed live as of Phase 10.3a:
const COMPANIES = [
  { slug: 'cred',    displayName: 'CRED' },
  { slug: 'meesho',  displayName: 'Meesho' }
];

// Cap per company — Lever often returns 50+ for big orgs; we slice early
// so the AI Extract chain doesn't hammer Gemini on a single fire.
const PER_COMPANY_LIMIT = 5;

const out = [];
const errors = [];

for (const c of COMPANIES) {
  try {
    const data = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.lever.co/v0/postings/${c.slug}?mode=json`,
      json: true,
    });
    const jobs = Array.isArray(data) ? data.slice(0, PER_COMPANY_LIMIT) : [];
    for (const j of jobs) {
      // Lever shape we care about:
      //   text             → job title
      //   hostedUrl        → public apply URL (one we link to & dedup on)
      //   descriptionPlain → readable plaintext (preferred for AI)
      //   description      → HTML (fallback)
      //   additionalPlain  → company blurb at the end of postings
      //   categories       → { commitment, department, location, team, allLocations[] }
      //   workplaceType    → 'remote' | 'on-site' | 'hybrid' | 'unspecified'
      const cat = j.categories || {};
      const locations = Array.isArray(cat.allLocations) && cat.allLocations.length > 0
        ? cat.allLocations.join(', ')
        : (cat.location || '');
      const body = (j.descriptionPlain || j.description || '') + '\n\n' + (j.additionalPlain || '');

      out.push({
        json: {
          title: j.text,
          link: j.hostedUrl,
          content: body,
          location: locations,
          workplaceType: j.workplaceType || '',
          commitment: cat.commitment || '',
          department: cat.department || '',
          team: cat.team || '',
          company: c.displayName,
          companySlug: c.slug,
          createdAt: j.createdAt || ''
        }
      });
    }
  } catch (e) {
    errors.push(`${c.slug}: ${(e && e.message) || e}`);
  }
}

// Fail loud rather than silently producing 0 items — that almost always
// means every slug 404'd and the COMPANIES list needs maintenance.
if (out.length === 0) {
  throw new Error('Lever fetch returned 0 jobs. Errors: ' + (errors.join(' | ') || 'none'));
}
return out;
